#include "engine/plugins/IPluginLoader.hpp"
#include <algorithm>
#include <unordered_map>
#include <utility>
namespace engine::plugins{namespace{class Loader final:public IPluginLoader{struct Record{PluginRuntimeInfo info;std::unique_ptr<PluginSandbox>sandbox;PluginLoadOptions options;};std::unordered_map<std::string,Record>records_;PluginTypeRegistry registry_;PluginLoadResult result(const Record&r)const{return{r.info.state==PluginState::Loaded,r.info.manifest.name,r.info.error_message,r.info.state};}public:bool register_plugin(const PluginManifest&m,const PluginLoadOptions&o,std::string&e)override{if(!m.validate(e))return false;if(records_.count(m.name)){e="duplicate_plugin";return false;}if(!o.permissions.all_granted()){e="permissions_denied";return false;}Record r;r.info.manifest=m;r.options=o;r.info.state=PluginState::Unloaded;r.info.library_path=o.library_path;r.sandbox=std::make_unique<PluginSandbox>(m.name,o.permissions);records_.emplace(m.name,std::move(r));return true;}PluginLoadResult load_result(const std::string&n,std::string&e)override{auto i=records_.find(n);if(i==records_.end()){e="plugin_not_found";return{false,n,e,PluginState::Error};}auto&r=i->second;if(r.info.manifest.abi==PluginAbi::Cpp&&!r.options.library_path.empty()&&!r.options.allow_dynamic_code){e="dynamic_code_not_permitted";r.info.error_message=e;r.info.state=PluginState::Error;return result(r);}r.info.error_message.clear();r.info.state=PluginState::Loaded;return result(r);}bool load(const std::string&n,std::string&e)override{return load_result(n,e).loaded;}bool unload(const std::string&n,std::string&e)override{auto i=records_.find(n);if(i==records_.end()){e="plugin_not_found";return false;}for(const auto&x:registry_.list_by_plugin(n))registry_.unregister(x.id);i->second.info.state=PluginState::Unloaded;return true;}PluginLoadResult reload_result(const std::string&n,std::string&e)override{if(!unload(n,e))return{false,n,e,PluginState::Error};return load_result(n,e);}bool reload(const std::string&n,std::string&e)override{return reload_result(n,e).loaded;}bool is_loaded(const std::string&n)const override{auto i=records_.find(n);return i!=records_.end()&&i->second.info.state==PluginState::Loaded;}std::vector<PluginRuntimeInfo>runtime()const override{std::vector<PluginRuntimeInfo>o;for(const auto&[_,r]:records_)o.push_back(r.info);std::sort(o.begin(),o.end(),[](const auto&a,const auto&b){return a.manifest.name<b.manifest.name;});return o;}const IPluginSandbox*sandbox(const std::string&n)const override{auto i=records_.find(n);return i==records_.end()?nullptr:i->second.sandbox.get();}IPluginTypeRegistry&registry()override{return registry_;}};}std::unique_ptr<IPluginLoader>create_plugin_loader(){return std::make_unique<Loader>();}}
